mapper.select:
SELECT * FROM ws_mcp_operation
WHERE id = #{id}
  AND tenant_id = #{tenantId}
  AND project_id = #{projectId}
  AND workspace_id = #{workspaceId}

mapper.update:
UPDATE ws_mcp_service_def
SET active_mcp_operation_id = #{operationId},
    last_updated_date = NOW()
WHERE id = #{serviceId}
  AND tenant_id = #{tenantId}
  AND project_id = #{projectId}
  AND workspace_id = #{workspaceId}
  AND deleted = 0
  AND active_mcp_operation_id IS NULL

UPDATE ws_mcp_service_def
SET active_mcp_operation_id = NULL
WHERE id = #{serviceId}
  AND active_mcp_operation_id = #{operationId}

mapper.select:
SELECT id FROM ws_mcp_operation
WHERE status = 'RUNNING' AND deadline_date < #{now}
ORDER BY deadline_date LIMIT #{limitCount}
